# Generated by Selenium IDE
# Test Case: Caregiver Functionality Test Suite (Post-Authentication)

import time
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC


class TestCaregiverFunctionality:

    def setup_method(self, method=None):
        self.driver = webdriver.Chrome()
        self.driver.maximize_window()   # Maximize window to prevent hidden elements
        self.wait = WebDriverWait(self.driver, 12)  # Explicit wait

        # Authenticate as Caregiver
        self.driver.get("http://localhost:5173/login")
        self.driver.execute_script("localStorage.clear(); sessionStorage.clear();")
        self.driver.delete_all_cookies()
        self.driver.refresh()

        email_field = self.wait.until(EC.visibility_of_element_located((By.NAME, "email")))
        email_field.clear()
        email_field.send_keys("sarah.jenkins@orphanage.com")

        password_field = self.wait.until(EC.visibility_of_element_located((By.NAME, "password")))
        password_field.clear()
        password_field.send_keys("Staff@123")

        submit_btn = self.wait.until(
            EC.element_to_be_clickable((By.CSS_SELECTOR, "button[type='submit']"))
        )
        self.driver.execute_script("arguments[0].scrollIntoView(true);", submit_btn)
        self.driver.execute_script("arguments[0].click();", submit_btn)

        self.wait.until(EC.url_contains("/staff-dashboard"))
        time.sleep(1)

    def teardown_method(self, method=None):
        self.driver.quit()

    def test_caregiver_dashboard_metrics(self):
        """1. Verify Caregiver Dashboard KPI cards, task progressions, and specializations."""
        self.driver.get("http://localhost:5173/staff-dashboard")
        time.sleep(1.5)

        # Verify page title and header
        page_text = self.driver.find_element(By.TAG_NAME, "body").text
        assert "Caregiver" in page_text or "Staff" in page_text, "Caregiver dashboard text missing"

        # Verify Specialization / Role overview cards exist
        spec_section = self.wait.until(
            EC.presence_of_element_located((By.XPATH, "//*[contains(text(), 'Specialization') or contains(text(), 'Responsibilities')]"))
        )
        assert spec_section is not None, "Staff/Caregiver Specializations card not found"
        print("[PASS] Caregiver Specializations & Dashboard metrics verified.")

    def test_caregiver_staff_directory_table(self):
        """2. Verify Staff & Caregiver directory table renders records."""
        self.driver.get("http://localhost:5173/staff-dashboard")
        time.sleep(1.5)

        # Check directory table presence
        table = self.wait.until(EC.presence_of_element_located((By.TAG_NAME, "table")))
        rows = self.driver.find_elements(By.CSS_SELECTOR, "table tbody tr")
        print(f"[PASS] Staff & Caregiver directory loaded with {len(rows)} rows.")
        assert len(rows) > 0, "Staff directory table has no rows."

    def test_caregiver_child_profile_search(self):
        """3. Verify Caregiver can access Child Profiles and perform search/filter."""
        self.driver.get("http://localhost:5173/child-profile")
        time.sleep(1.5)

        assert "/child-profile" in self.driver.current_url

        # Check search input
        search_input = self.wait.until(
            EC.presence_of_element_located((By.XPATH, "//input[@placeholder[contains(., 'Search')]]"))
        )
        search_input.clear()
        search_input.send_keys("A")
        time.sleep(0.5)

        rows = self.driver.find_elements(By.XPATH, "//table//tbody//tr")
        print(f"[PASS] Child Profile search executed by Caregiver. Filtered records: {len(rows)}.")
        assert len(rows) > 0, "No child records displayed after search."

    def test_caregiver_attendance_module(self):
        """4. Verify Caregiver can navigate to Child Attendance recording module."""
        self.driver.get("http://localhost:5173/child-attendance")
        time.sleep(1.5)

        assert "/child-attendance" in self.driver.current_url
        page_body = self.driver.find_element(By.TAG_NAME, "body").text
        assert "Attendance" in page_body, "Attendance module page title missing."
        print("[PASS] Child Attendance module loaded successfully for Caregiver.")


if __name__ == "__main__":
    test = TestCaregiverFunctionality()
    test.setup_method()
    try:
        print("\n--- Running Caregiver Functionality Tests ---")
        test.test_caregiver_dashboard_metrics()
        test.test_caregiver_staff_directory_table()
        test.test_caregiver_child_profile_search()
        test.test_caregiver_attendance_module()
        print("\n>>> ALL CAREGIVER FUNCTIONALITY TESTS PASSED SUCCESSFULLY! <<<\n")
    finally:
        test.teardown_method()
